(function () {
'use strict';
var doc = document;
function track(name, params) {
if (typeof window.gtag !== 'function') return;
params = params || {};
params.page_path = location.pathname;
params.market = 'usa';
window.gtag('event', name, params);
}
var burger = doc.getElementById('usBurger');
var menu = doc.getElementById('usMenu');
if (burger && menu) {
var closeBtn = menu.querySelector('.usmenu__close');
var focusables = function () { return menu.querySelectorAll('a[href], button:not([disabled])'); };
var open = function () {
menu.hidden = false;
burger.setAttribute('aria-expanded', 'true');
doc.body.classList.add('menu-open');
closeBtn.focus();
};
var close = function (restore) {
if (menu.hidden) return;
menu.hidden = true;
burger.setAttribute('aria-expanded', 'false');
doc.body.classList.remove('menu-open');
if (restore !== false) burger.focus();
};
burger.addEventListener('click', open);
closeBtn.addEventListener('click', function () { close(); });
menu.addEventListener('click', function (e) { if (e.target.closest('a')) close(false); });
doc.addEventListener('keydown', function (e) {
if (menu.hidden) return;
if (e.key === 'Escape') { e.preventDefault(); close(); return; }
if (e.key !== 'Tab') return;
var f = focusables(), first = f[0], last = f[f.length - 1];
if (e.shiftKey && doc.activeElement === first) { e.preventDefault(); last.focus(); }
else if (!e.shiftKey && doc.activeElement === last) { e.preventDefault(); first.focus(); }
});
window.addEventListener('resize', function () { if (window.innerWidth >= 1100) close(false); });
}
var regions = doc.querySelectorAll('details.region');
doc.addEventListener('click', function (e) {
regions.forEach(function (d) { if (d.open && !d.contains(e.target)) d.open = false; });
});
doc.addEventListener('keydown', function (e) {
if (e.key !== 'Escape') return;
regions.forEach(function (d) { if (d.open) { d.open = false; d.querySelector('summary').focus(); } });
});
doc.addEventListener('click', function (e) {
var a = e.target.closest && e.target.closest('a[href]');
if (!a) return;
var h = a.getAttribute('href') || '';
var where = a.getAttribute('data-loc') || (a.closest('header') ? 'header' : a.closest('footer') ? 'footer' : a.closest('.usbar') ? 'sticky_bar' : 'body');
if (/^tel:/i.test(h)) track('phone_click', { link_location: where });
else if (/^mailto:/i.test(h)) track('email_click', { link_location: where });
}, true);
var form = doc.getElementById('usForm');
if (!form) return;
var status = doc.getElementById('usFormStatus');
var btn = form.querySelector('button[type="submit"]');
var started = Date.now();
var label = btn.textContent;
var fallback = 'Please call <a href="tel:+16173869074">+1 (617) 386-9074</a> or email <a href="mailto:contact@amanadigitalusa.com">contact@amanadigitalusa.com</a>.';
var MESSAGES = {
invalid: 'Some fields need attention. Please check them and try again.',
too_fast: 'That was very quick. Please wait a few seconds and send again.',
rate_limited: 'Too many requests from your connection. Please try again later.',
send_failed: 'Your message could not be sent because of a problem on our side.',
};
var show = function (ok, html) {
status.className = 'ustatus ' + (ok ? 'ustatus--ok' : 'ustatus--err');
status.innerHTML = html;
status.setAttribute('tabindex', '-1');
status.focus();
};
form.addEventListener('submit', function (e) {
e.preventDefault();
if (!form.checkValidity()) { form.reportValidity(); return; }
var data = new FormData(form);
data.set('fs', String(Math.round((Date.now() - started) / 1000)));
btn.disabled = true;
btn.textContent = 'Sending…';
status.className = 'ustatus';
status.textContent = '';
fetch(form.action, { method: 'POST', body: data, headers: { Accept: 'application/json' }, credentials: 'same-origin' })
.then(function (res) { return res.json().catch(function () { return { ok: false, error: 'send_failed' }; }).then(function (j) { return { http: res.ok, j: j }; }); })
.then(function (r) {
if (r.http && r.j && r.j.ok === true) {
show(true, '<strong>Thank you, your message was sent.</strong> We will reply by email or phone. If it is urgent, call <a href="tel:+16173869074">+1 (617) 386-9074</a>.');
track('generate_lead', { method: 'form', lead_type: 'agency', service: String(data.get('service') || '') });
form.reset();
started = Date.now();
} else {
show(false, (MESSAGES[r.j && r.j.error] || MESSAGES.send_failed) + ' ' + fallback);
}
})
.catch(function () { show(false, 'We could not reach our server (check your connection). ' + fallback); })
.then(function () { btn.disabled = false; btn.textContent = label; });
});
})();
